const DEFAULT_WORKFLOW_NAME = 'BESTAL_RESUME_AI_SCREENING';
const DEFAULT_WORKFLOW_VERSION = '1.0.0';

const req = $input.first();
const headers = req.json.headers || {};
const body = req.json.body ?? req.json;

const workflowName = String(body?.workflowName || DEFAULT_WORKFLOW_NAME).trim();
const workflowVersion = String(body?.workflowVersion || DEFAULT_WORKFLOW_VERSION).trim();

const secretHeader = headers['x-n8n-webhook-secret'] || headers['X-N8N-Webhook-Secret'];
const auth = headers.authorization || headers.Authorization || '';
const bearer = typeof auth === 'string' && auth.toLowerCase().startsWith('bearer ')
  ? auth.slice(7).trim()
  : '';
const expected = $env.N8N_WEBHOOK_SECRET;

if (expected) {
  const ok = (secretHeader && secretHeader === expected) || (bearer && bearer === expected);
  if (!ok) {
    return [{
      json: {
        ok: false,
        stage: 'Validate Request',
        errorCode: 'UNAUTHORIZED',
        errorMessage: 'Invalid or missing webhook secret',
        jobId: Number(body?.jobId) || null,
        candidateId: Number(body?.candidateId) || null,
        workflowName: workflowName,
        workflowVersion: workflowVersion,
      }
    }];
  }
}

function asPositiveInt(value, field) {
  const n = typeof value === 'number' ? value : Number(String(value ?? '').trim());
  if (!Number.isInteger(n) || n <= 0) {
    throw new Error(`${field} must be a positive integer`);
  }
  if (typeof value === 'string' && /[a-f0-9-]{36}/i.test(value)) {
    throw new Error(`${field} must not be a UUID`);
  }
  return n;
}

try {
  const jobId = asPositiveInt(body.jobId, 'jobId');
  let candidateId = null;
  if (body.candidateId != null && body.candidateId !== '') {
    candidateId = asPositiveInt(body.candidateId, 'candidateId');
  }
  const documentId = asPositiveInt(body.documentId, 'documentId');
  const requestedBy = asPositiveInt(body.requestedBy, 'requestedBy');
  const documentUrl = String(body.documentUrl || '').trim();
  if (!/^https?:\/\//i.test(documentUrl)) {
    throw new Error('documentUrl must be an http(s) URL');
  }

  return [{
    json: {
      ok: true,
      jobId,
      candidateId,
      documentId,
      requestedBy,
      documentUrl,
      workflowName: workflowName,
      workflowVersion: workflowVersion,
    }
  }];
} catch (error) {
  return [{
    json: {
      ok: false,
      stage: 'Validate Request',
      errorCode: 'INVALID_INPUT',
      errorMessage: error.message || 'Invalid input',
      jobId: Number(body?.jobId) || null,
      candidateId: Number(body?.candidateId) || null,
      workflowName: workflowName,
      workflowVersion: workflowVersion,
    }
  }];
}

const ctx = $('Extract Input').first().json;
const item = $input.first();
const text = String(item.json.text || item.json.data || item.json.content || '').trim();

if (!text || text.length < 40) {
  return [{
    json: {
      ok: false,
      stage: 'Extract Resume Text',
      errorCode: 'RESUME_EXTRACTION_FAILED',
      errorMessage: 'Unable to extract resume text',
      jobId: ctx.jobId,
      candidateId: ctx.candidateId,
      workflowName: ctx.workflowName,
      workflowVersion: ctx.workflowVersion,
    }
  }];
}

const resumeText = text.slice(0, 100000);
const truncated = text.length > 100000;

const schema = {
  confidence: 'number 0-1',
  warnings: ['string'],
  firstName: 'string',
  lastName: 'string',
  email: 'string|null',
  phone: 'string|null',
  location: 'string|null',
  timezone: 'string|null',
  headline: 'string|null',
  yearsExperience: 'number|null',
  primaryRole: 'string',
  summary: 'string',
  aiSummary: 'string',
  strengths: 'string',
  weaknesses: 'string',
  riskFlags: 'string',
  community: 'string',
  skillCategory: 'string',
  bestalScore: '0-100 int',
  skills: [{
    name: 'short skill label',
    skillCategory: 'string',
    proficiency: 'BEGINNER|INTERMEDIATE|ADVANCED|EXPERT',
    skillYearsExperience: 'number|null',
    isPrimary: 'boolean'
  }]
};

const prompt = `You are an expert resume extraction and scoring engine for BesTal.\nReturn ONLY valid JSON (camelCase) matching this schema:\n${JSON.stringify(schema, null, 2)}\n\nRules:\n- Never invent identity fields not present in the resume.\n- Each skills[].name is ONE short label (max 60 chars), never a comma-list.\n- Include skillCategory, proficiency, skillYearsExperience, isPrimary per skill.\n- Prefer 8-20 skills; mark 1-6 isPrimary=true.\n- If name missing, leave firstName/lastName empty and add a warning.\n${truncated ? '- Resume text was truncated; note in warnings.\n' : ''}\nResume text:\n\"\"\"\n${resumeText}\n\"\"\"\n\nReturn ONLY JSON.`;

return [{
  json: {
    ok: true,
    jobId: ctx.jobId,
    candidateId: ctx.candidateId,
    documentId: ctx.documentId,
    requestedBy: ctx.requestedBy,
    workflowName: ctx.workflowName,
    workflowVersion: ctx.workflowVersion,
    prompt,
  }
}];

const ctx = $('Prepare AI Prompt').first().json;
const raw = $input.first().json;

let content = raw.text || raw.message?.content || raw.content || raw.output || raw;
if (Array.isArray(content)) {
  content = content.map((p) => p.text || p).join('\n');
}
if (typeof content !== 'string') {
  content = JSON.stringify(content);
}

content = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/,'');

let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  return [{
    json: {
      ok: false,
      stage: 'Validate Structured JSON',
      errorCode: 'AI_OUTPUT_INVALID',
      errorMessage: 'OpenAI returned invalid JSON',
      jobId: ctx.jobId,
      candidateId: ctx.candidateId,
      workflowName: ctx.workflowName,
      workflowVersion: ctx.workflowVersion,
    }
  }];
}

const firstName = String(parsed.firstName || parsed.candidate?.firstName || '').trim();
const lastName = String(parsed.lastName || parsed.candidate?.lastName || '').trim();
const aiSummary = String(parsed.aiSummary || '').trim();
if (!firstName && !lastName && !aiSummary) {
  return [{
    json: {
      ok: false,
      stage: 'Validate Structured JSON',
      errorCode: 'AI_OUTPUT_INVALID',
      errorMessage: 'AI output must include a name or aiSummary',
      jobId: ctx.jobId,
      candidateId: ctx.candidateId,
      workflowName: ctx.workflowName,
      workflowVersion: ctx.workflowVersion,
    }
  }];
}

return [{
  json: {
    ok: true,
    jobId: ctx.jobId,
    candidateId: ctx.candidateId,
    documentId: ctx.documentId,
    requestedBy: ctx.requestedBy,
    workflowName: ctx.workflowName,
    workflowVersion: ctx.workflowVersion,
    ai: parsed,
  }
}];

const item = $input.first().json;
const ai = item.ai || {};
const PROF = new Set(['BEGINNER', 'INTERMEDIATE', 'ADVANCED', 'EXPERT']);

const skillsIn = Array.isArray(ai.skills) ? ai.skills : [];
const byName = new Map();

for (const skill of skillsIn) {
  const name = String(skill.name || skill.skillName || '').trim().slice(0, 150);
  if (!name) continue;
  const key = name.toLowerCase();
  let proficiency = String(skill.proficiency || skill.proficiencyLevel || 'INTERMEDIATE').toUpperCase();
  if (!PROF.has(proficiency)) proficiency = 'INTERMEDIATE';
  const years = Number(skill.skillYearsExperience ?? skill.yearsExperience);
  const next = {
    name,
    skillName: name,
    skillCategory: String(skill.skillCategory || ai.skillCategory || ai.community || '').trim() || undefined,
    proficiency,
    proficiencyLevel: proficiency,
    skillYearsExperience: Number.isFinite(years) ? years : undefined,
    yearsExperience: Number.isFinite(years) ? years : undefined,
    isPrimary: Boolean(skill.isPrimary),
  };
  const prev = byName.get(key);
  if (!prev) {
    byName.set(key, next);
    continue;
  }
  byName.set(key, {
    ...prev,
    ...next,
    isPrimary: prev.isPrimary || next.isPrimary,
    skillYearsExperience: Math.max(prev.skillYearsExperience || 0, next.skillYearsExperience || 0) || undefined,
    yearsExperience: Math.max(prev.yearsExperience || 0, next.yearsExperience || 0) || undefined,
  });
}

const skills = [...byName.values()];
let seenPrimary = false;
for (const s of skills) {
  if (s.isPrimary) {
    if (seenPrimary) s.isPrimary = false;
    else seenPrimary = true;
  }
}
if (!seenPrimary && skills[0]) skills[0].isPrimary = true;

const result = {
  confidence: typeof ai.confidence === 'number' ? ai.confidence : 0.8,
  firstName: ai.firstName || ai.candidate?.firstName || '',
  lastName: ai.lastName || ai.candidate?.lastName || '',
  email: ai.email || ai.candidate?.email || undefined,
  phone: ai.phone || ai.candidate?.phone || undefined,
  location: ai.location || ai.candidate?.location || undefined,
  timezone: ai.timezone || ai.candidate?.timezone || undefined,
  headline: ai.headline || ai.candidate?.headline || undefined,
  yearsExperience: ai.yearsExperience ?? ai.candidate?.yearsExperience ?? undefined,
  primaryRole: ai.primaryRole || undefined,
  summary: ai.summary || ai.candidate?.summary || undefined,
  aiSummary: ai.aiSummary || undefined,
  strengths: ai.strengths || undefined,
  weaknesses: ai.weaknesses || undefined,
  riskFlags: ai.riskFlags || undefined,
  community: ai.community || undefined,
  skillCategory: ai.skillCategory || ai.community || undefined,
  bestalScore: ai.bestalScore ?? undefined,
  recommendedClientRate: ai.recommendedClientRate ?? undefined,
  recommendedCandidateRate: ai.recommendedCandidateRate ?? undefined,
  skills,
  warnings: Array.isArray(ai.warnings) ? ai.warnings : [],
  candidate: {
    firstName: ai.firstName || ai.candidate?.firstName || '',
    lastName: ai.lastName || ai.candidate?.lastName || '',
    email: ai.email || ai.candidate?.email || undefined,
    phone: ai.phone || ai.candidate?.phone || undefined,
    location: ai.location || ai.candidate?.location || undefined,
    timezone: ai.timezone || ai.candidate?.timezone || undefined,
    headline: ai.headline || ai.candidate?.headline || undefined,
    summary: ai.summary || ai.candidate?.summary || undefined,
    yearsExperience: ai.yearsExperience ?? ai.candidate?.yearsExperience ?? undefined,
  },
};

return [{
  json: {
    jobId: item.jobId,
    candidateId: item.candidateId,
    workflowName: item.workflowName,
    workflowVersion: item.workflowVersion,
    result,
  }
}];

const item = $input.first().json;
return [{
  json: {
    callbackBody: {
      jobId: item.jobId,
      ...(item.candidateId != null && Number(item.candidateId) > 0 ? { candidateId: Number(item.candidateId) } : {}),
      status: 'COMPLETED',
      result: item.result,
    },
    jobId: item.jobId,
    candidateId: item.candidateId,
    workflowName: item.workflowName,
    workflowVersion: item.workflowVersion,
  }
}];

// Webhook already answered by Respond Trigger Accepted; pipeline finished via internal callback.
return [{
  json: {
    ok: true,
    stage: 'Complete',
    jobId: $('Prepare Callback Payload').first().json.jobId,
    workflowName: $('Prepare Callback Payload').first().json.workflowName,
    workflowVersion: $('Prepare Callback Payload').first().json.workflowVersion,
  }
}];

const item = $input.first().json;
const jobId = Number(item.jobId);
const candidateId = Number(item.candidateId);

if (!Number.isInteger(jobId) || jobId <= 0) {
  return [{
    json: {
      skipCallback: true,
      respondBody: {
        ok: false,
        errorCode: item.errorCode || 'INVALID_INPUT',
        errorMessage: item.errorMessage || 'Invalid input',
      }
    }
  }];
}

return [{
  json: {
    skipCallback: false,
    jobId,
    candidateId,
    callbackBody: {
      jobId,
      ...(Number.isInteger(candidateId) && candidateId > 0 ? { candidateId } : {}),
      status: 'FAILED',
      errorCode: item.errorCode || 'INTERNAL_ERROR',
      errorMessage: item.errorMessage || 'Resume AI screening failed',
      result: {},
    },
    respondBody: {
      ok: false,
      jobId,
      candidateId,
      errorCode: item.errorCode || 'INTERNAL_ERROR',
      workflowName: item.workflowName,
      workflowVersion: item.workflowVersion,
    }
  }
}];

const ctx = $('Extract Input').first().json;
return [{
  json: {
    ok: false,
    stage: 'Download Resume From Signed URL',
    errorCode: 'RESUME_DOWNLOAD_FAILED',
    errorMessage: 'Failed to download resume from signed URL',
    jobId: ctx.jobId,
    candidateId: ctx.candidateId,
    workflowName: ctx.workflowName,
    workflowVersion: ctx.workflowVersion,
  }
}];

const ctx = $('Extract Input').first().json;
return [{
  json: {
    ok: false,
    stage: 'Extract Resume Text',
    errorCode: 'RESUME_EXTRACTION_FAILED',
    errorMessage: 'Unable to extract resume text',
    jobId: ctx.jobId,
    candidateId: ctx.candidateId,
    workflowName: ctx.workflowName,
    workflowVersion: ctx.workflowVersion,
  }
}];

const ctx = $('Prepare AI Prompt').first().json;
return [{
  json: {
    ok: false,
    stage: 'OpenAI',
    errorCode: 'OPENAI_FAILED',
    errorMessage: 'OpenAI request failed after retries',
    jobId: ctx.jobId,
    candidateId: ctx.candidateId,
    workflowName: ctx.workflowName,
    workflowVersion: ctx.workflowVersion,
  }
}];
